def clean(df):
    df = df.drop_duplicates()
    df['Category'] = df['Category'].replace(['Office Suplies', 'Furnture'], ['Office Supplies', 'Furniture'])
    df = df[df['Quantity'] > 0]
    df['Revenue'] = df['Quantity'] * df['Price']
    return df

def answer(df):
    result = df.groupby('Category')['Price'].mean().to_dict()
    return result}
